@Test
public void testAtomicBoolean() {
    // in a condition
    JexlScript e = JEXL.createScript("if (x) 1 else 2;", "x");
    final JexlContext jc = new MapContext();
    final AtomicBoolean ab = new AtomicBoolean(false);
    Object o;
    o = e.execute(jc, ab);
    Assert.assertEquals("Result is not 2", new Integer(2), o);
    ab.set(true);
    o = e.execute(jc, ab);
    Assert.assertEquals("Result is not 1", new Integer(1), o);
    // in a binary logical op
    e = JEXL.createScript("x && y", "x", "y");
    ab.set(true);
    o = e.execute(jc, ab, Boolean.FALSE);
    Assert.assertFalse((Boolean) o);
    ab.set(true);
    o = e.execute(jc, ab, Boolean.TRUE);
    Assert.assertTrue((Boolean) o);
    ab.set(false);
    o = e.execute(jc, ab, Boolean.FALSE);
    Assert.assertFalse((Boolean) o);
    ab.set(false);
    o = e.execute(jc, ab, Boolean.FALSE);
    Assert.assertFalse((Boolean) o);
    // in arithmetic op
    e = JEXL.createScript("x + y", "x", "y");
    ab.set(true);
    o = e.execute(jc, ab, 10);
    Assert.assertEquals(11, o);
    o = e.execute(jc, 10, ab);
    Assert.assertEquals(11, o);
    o = e.execute(jc, ab, 10.d);
    Assert.assertEquals(11.d, (Double) o, EPSILON);
    o = e.execute(jc, 10.d, ab);
    Assert.assertEquals(11.d, (Double) o, EPSILON);
    final BigInteger bi10 = BigInteger.TEN;
    ab.set(false);
    o = e.execute(jc, ab, bi10);
    Assert.assertEquals(bi10, o);
    o = e.execute(jc, bi10, ab);
    Assert.assertEquals(bi10, o);
    final BigDecimal bd10 = BigDecimal.TEN;
    ab.set(false);
    o = e.execute(jc, ab, bd10);
    Assert.assertEquals(bd10, o);
    o = e.execute(jc, bd10, ab);
    Assert.assertEquals(bd10, o);
    // in a (the) monadic op
    e = JEXL.createScript("!x", "x");
    ab.set(true);
    o = e.execute(jc, ab);
    Assert.assertFalse((Boolean) o);
    ab.set(false);
    o = e.execute(jc, ab);
    Assert.assertTrue((Boolean) o);
    // in a (the) monadic op
    e = JEXL.createScript("-x", "x");
    ab.set(true);
    o = e.execute(jc, ab);
    Assert.assertFalse((Boolean) o);
    ab.set(false);
    o = e.execute(jc, ab);
    Assert.assertTrue((Boolean) o);
}

@Test
public void testCompare() {
    // JEXL doesn't support more than one operator in the same expression, for example: 1 == 1 == 1
    final Object[] EXPRESSIONS = { // Basic compare
    "1 == 1", true, "1 != 1", false, "1 != 2", true, "1 > 2", false, "1 >= 2", false, "1 < 2", true, "1 <= 2", true, // Int <-> Float Coercion
    "1.0 == 1", true, "1 == 1.0", true, "1.1 != 1", true, "1.1 < 2", true, // Big Decimal <-> Big Integer Coercion
    "1.0b == 1h", true, "1h == 1.0b", true, "1.1b != 1h", true, "1.1b < 2h", true, // Mix all type of numbers
    // long and int
    "1l == 1.0", // long and int
    true, // double and float
    "1.0d == 1.0f", // double and float
    true, "1l == 1.0b", true, "1l == 1h", true, "1.0d == 1.0b", true, "1.0f == 1.0b", true, "1.0d == 1h", true, "1.0f == 1h", true, // numbers and strings
    "'1' == 1", true, "'1' == 1l", true, "'1' == 1h", true, // empty string is coerced to zero (ECMA compliance)
    "'' == 0", // empty string is coerced to zero (ECMA compliance)
    true, "'1.0' == 1", true, "'1.0' == 1.0f", true, "'1.0' == 1.0d", true, "'1.0' == 1.0b", true, "'1.01' == 1.01", true, "'1.01' == 1", false, "'1.01' == 1b", false, "'1.01' == 1h", false, "'1.00001' == 1b", false, "'1.00001' == 1h", false, "'1.00000001' == 1", false, "'1.00000001' == 1b", false, "'1.00000001' == 1h", false, "1.0 >= '1'", true, "1.0 > '1'", false };
    final JexlEngine jexl = new JexlBuilder().create();
    final JexlContext jc = new EmptyTestContext();
    JexlExpression expression;
    for (int e = 0; e < EXPRESSIONS.length; e += 2) {
        final String stext = (String) EXPRESSIONS[e];
        final Object expected = EXPRESSIONS[e + 1];
        expression = jexl.createExpression(stext);
        final Object result = expression.evaluate(jc);
        Assert.assertEquals("failed on " + stext, expected, result);
    }
}

