/**
 * Ternary operator condition undefined or null evaluates to false
 * independently of engine flags.
 * @throws Exception
 */
@Test
public void testTernary() throws Exception {
    final JexlEngine jexl = JEXL;
    final JexlEvalContext jc = new JexlEvalContext();
    final JexlOptions options = jc.getEngineOptions();
    final JexlExpression e = jexl.createExpression("x.y.z = foo ?'bar':'quux'");
    Object o;
    // undefined foo
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
    }
    jc.set("foo", null);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
    }
    jc.set("foo", Boolean.FALSE);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
    }
    jc.set("foo", Boolean.TRUE);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be bar", "bar", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be bar", "bar", o);
    }
    debuggerCheck(jexl);
}

/**
 * Ternary operator condition undefined or null evaluates to false
 * independently of engine flags; same for null coalescing operator.
 * @throws Exception
 */
@Test
public void testTernaryShorthand() throws Exception {
    final JexlEvalContext jc = new JexlEvalContext();
    final JexlOptions options = jc.getEngineOptions();
    final JexlExpression e = JEXL.createExpression("x.y.z = foo?:'quux'");
    final JexlExpression f = JEXL.createExpression("foo??'quux'");
    Object o;
    // undefined foo
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
    }
    jc.set("foo", null);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
    }
    jc.set("foo", Boolean.FALSE);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertEquals("Should be false", false, o);
    }
    jc.set("foo", Double.NaN);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertTrue("Should be NaN", Double.isNaN((Double) o));
    }
    jc.set("foo", "");
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertEquals("Should be empty string", "", o);
    }
    jc.set("foo", "false");
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertEquals("Should be 'false'", "false", o);
    }
    jc.set("foo", 0d);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertEquals("Should be 0", 0.d, o);
    }
    jc.set("foo", 0);
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be quux", "quux", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be quux", "quux", o);
        o = f.evaluate(jc);
        Assert.assertEquals("Should be 0", 0, o);
    }
    jc.set("foo", "bar");
    for (int l = 0; l < 4; ++l) {
        options.setStrict((l & 1) == 0);
        options.setSilent((l & 2) != 0);
        o = e.evaluate(jc);
        Assert.assertEquals("Should be bar", "bar", o);
        o = jc.get("x.y.z");
        Assert.assertEquals("Should be bar", "bar", o);
    }
    debuggerCheck(JEXL);
}

