@Test
public void testSecurePermissions() {
    Assert.assertNotNull(JexlTestCase.SECURE);
    List<Class<?>> acs = Arrays.asList(java.lang.Runtime.class, java.math.BigDecimal.class, java.text.SimpleDateFormat.class, java.util.Map.class);
    for (Class<?> ac : acs) {
        Package p = ac.getPackage();
        Assert.assertNotNull(ac.getName(), p);
        Assert.assertTrue(ac.getName(), JexlTestCase.SECURE.allow(p));
    }
    List<Class<?>> nacs = Arrays.asList(java.lang.annotation.ElementType.class, java.lang.instrument.ClassDefinition.class, java.lang.invoke.CallSite.class, java.lang.management.BufferPoolMXBean.class, java.lang.ref.SoftReference.class, java.lang.reflect.Method.class);
    for (Class<?> nac : nacs) {
        Package p = nac.getPackage();
        Assert.assertNotNull(nac.getName(), p);
        Assert.assertFalse(nac.getName(), JexlTestCase.SECURE.allow(p));
    }
}

