    assertExpression(jc, "aFloat ne aDouble", Boolean.TRUE);
    assertExpression(jc, "aFloat == aDouble", Boolean.FALSE);
    assertExpression(jc, "aFloat != aDouble", Boolean.TRUE);
    // test number and character equality
