    // 1
    asserter.assertExpression("i = 1", 1);
    // 1 + 1 = 2
    asserter.assertExpression("i = i + 1", 2);
    // 2 - 1 = 1
    asserter.assertExpression("i = i - 1", 1);
    // 1 * 2 = 2
    asserter.assertExpression("i = i * 2", 2);
    // 2 / 2 = 1
    asserter.assertExpression("i = i / 2", 1);
    // 1 % 1 = 1
    asserter.assertExpression("i = i % 2", 1);
    // 1 ^ 0 = 1
    asserter.assertExpression("i = i ^ 0", 1L);
    // 1 << 1 = 2
    asserter.assertExpression("i = i << 1", 2L);
    // 1 >> 1 = 1
    asserter.assertExpression("i = i >> 1", 1L);
    // 1 >>> 1 = 0
    asserter.assertExpression("i = i >>> 1", 0L);
    // reset
    asserter.assertExpression("i = 1", 1);
    asserter.assertExpression("i += 1", 2);
    asserter.assertExpression("i -= 1", 1);
    asserter.assertExpression("i *= 2", 2);
    asserter.assertExpression("i /= 2", 1);
    asserter.assertExpression("i %= 2", 1);
    asserter.assertExpression("i ^= 0", 1L);
    asserter.assertExpression("i <<= 1", 2L);
    asserter.assertExpression("i >>= 1", 1L);
    asserter.assertExpression("i >>>= 1", 0L);
    // reset
    asserter.assertExpression("i = 1", 1);
    asserter.assertExpression("++i", 2);
    asserter.assertExpression("--i", 1);
    asserter.assertExpression("i++", 1);
    asserter.assertExpression("i--", 2);
